using System.Collections.ObjectModel;
using System.Diagnostics;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Interop;
using System.Runtime.InteropServices;
using Microsoft.Win32;
using NovaForge.Core;
using Condition=System.Windows.Automation.Condition;
using Validation=NovaForge.Core.Validation;
namespace NovaForge.Automation;
public sealed class RecorderWindow:Window
{
 private readonly RecorderSession session;private readonly ObservableCollection<UiStep> steps=[];private readonly ListBox list=new();private readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap};private readonly TextBox name=new();private readonly CheckBox other=new(){Content="Weitere Installations-/Treiberfenster automatisch aufnehmen",IsChecked=true};
 private MouseRecorder? recorder;private Process? installer;private readonly HashSet<int> extra=[];private readonly RecordedProfile profile;private string verification="";private bool testing,saving;private const string Output=@"C:\NovaForgeOutput";
 public RecorderWindow(string sessionPath)
 {
  if(!Environment.UserName.Equals("WDAGUtilityAccount",StringComparison.OrdinalIgnoreCase)||!Path.GetFullPath(sessionPath).Equals(@"C:\NovaForgeInput\session.json",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Aufzeichnung wird ausschließlich in der vorbereiteten Windows Sandbox gestartet.");
  session=System.Text.Json.JsonSerializer.Deserialize<RecorderSession>(File.ReadAllText(sessionPath),Project.JsonOptions)??throw new InvalidDataException("Sitzung fehlt.");
  var installerPath=Path.GetFullPath(session.InstallerFileName,@"C:\NovaForgeInput");if(!FolderMedia.Within(installerPath,@"C:\NovaForgeInput")||session.Mode is not ("Record" or "Test"))throw new InvalidDataException("Sitzung ungültig.");
  profile=new(){InstallerSha256=session.InstallerSha256,InstallerArguments=session.InstallerArguments,RequiresElevation=true,PackageSha256=session.PackageSha256,DisplayName=session.DisplayName};
  Style=(Style)FindResource(typeof(Window));Title="NovaForge Beta · Installationsaufnahme";Width=980;Height=780;MinWidth=760;MinHeight=600;
  var panel=new DockPanel{Margin=new Thickness(24)};Content=panel;var head=new StackPanel();DockPanel.SetDock(head,Dock.Top);panel.Children.Add(head);
  head.Children.Add(new TextBlock{Text="BETA · Installation aufnehmen",FontSize=24,FontWeight=FontWeights.Bold});head.Children.Add(new TextBlock{Text="F7: fokussierte Aktion manuell vormerken. F8: Text aufnehmen. F9: Lizenz/Kennwort ausdrücklich eingeben. UAC bleibt manuell. Treiber mit echter Hardware können in Sandbox nicht funktionieren.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,12)});
  head.Children.Add(new TextBlock{Text="Name meiner Aufnahme"});name.Text=session.DisplayName;head.Children.Add(name);head.Children.Add(other);other.Checked+=(_,_)=>{if(recorder!=null)recorder.CaptureOtherWindows=true;};other.Unchecked+=(_,_)=>{if(recorder!=null)recorder.CaptureOtherWindows=false;};
  var buttons=new WrapPanel();head.Children.Add(buttons);void Add(string label,RoutedEventHandler handler){var button=new Button{Content=label,Margin=new Thickness(0,0,8,8)};button.Click+=handler;buttons.Children.Add(button);}
  if(session.Mode=="Record"){
   Add("Aufnahme starten",async(_,_)=>await Start());Add("Letzten Schritt entfernen",(_,_)=>{if(steps.Count>0)steps.RemoveAt(steps.Count-1);});
   Add("Prüfdatei wählen",(_,_)=>{var d=new OpenFileDialog{Title="Neu installierte Datei wählen (auch Windows/System32/drivers)"};if(d.ShowDialog(this)==true){if(FolderMedia.Within(d.FileName,@"C:\NovaForgeInput"))throw new InvalidDataException("Eine installierte Zieldatei wählen, keine Eingabekopie.");verification=UiAutomationEngine.Normalize(d.FileName);status.Text="Prüfdatei: "+verification;}});
   Add("Aufnahme speichern",async(_,_)=>await Save(false));Add("Speichern und schließen",async(_,_)=>await Save(true));Add("Zusatzfenster verbinden",(_,_)=>ConnectWindow());
  }
  DockPanel.SetDock(status,Dock.Bottom);status.Margin=new Thickness(0,14,0,0);panel.Children.Add(status);list.ItemsSource=steps;panel.Children.Add(list);
  Closing+=(_,e)=>{if(testing||saving){e.Cancel=true;status.Text="Laufenden Test oder Speichervorgang zuerst abschließen lassen.";}else recorder?.Dispose();};
  SourceInitialized+=(_,_)=>{var source=(HwndSource)PresentationSource.FromVisual(this);source.AddHook((IntPtr h,int msg,IntPtr w,IntPtr l,ref bool handled)=>{if(msg==0x0312){try{if(w.ToInt32()==782)CaptureSecret();else if(w.ToInt32()==780)recorder?.CaptureFocusedAction();else recorder?.CaptureFocusedText();}catch(Exception e){Error(e);}handled=true;}return IntPtr.Zero;});foreach(var key in new[]{(780,0x76),(781,0x77),(782,0x78)})if(!RegisterHotKey(new WindowInteropHelper(this).Handle,key.Item1,0,(uint)key.Item2))status.Text="Eine Aufnahmetaste ist bereits belegt. Registrierung für F7/F8/F9 prüfen.";};
  Closed+=(_,_)=>{foreach(var id in new[]{780,781,782})UnregisterHotKey(new WindowInteropHelper(this).Handle,id);};Loaded+=async(_,_)=>{if(session.Mode=="Test")await Test();else await Start();};
 }
 private void Error(Exception e){status.Text=e.Message;try{Directory.CreateDirectory(Output);File.AppendAllText(Path.Combine(Output,"record-errors.log"),DateTimeOffset.Now+" "+e.Message+Environment.NewLine);}catch{}}
 private void CaptureSecret(){if(recorder==null)throw new InvalidOperationException("Aufnahme zuerst starten.");var target=recorder.SecretTarget();var window=new Window{Title="Vertraulichen Wert aufnehmen",Owner=this,Width=620,Height=330,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(24)};panel.Children.Add(new TextBlock{Text="Wert für das fokussierte Feld eingeben. Profil und ISO enthalten ihn im Klartext; Zugriff beschränken.",TextWrapping=TextWrapping.Wrap});var input=new PasswordBox{Margin=new Thickness(0,16,0,16),Background=System.Windows.Media.Brushes.DarkSlateGray,Foreground=System.Windows.Media.Brushes.White};panel.Children.Add(input);var button=new Button{Content="Wert ausdrücklich aufnehmen"};button.Click+=(_,_)=>{try{var step=recorder.CaptureSecret(target,input.Password);input.Clear();window.Close();UiAutomationEngine.Apply(target,step);status.Text="Vertraulicher Schritt aufgenommen.";}catch(Exception e){Error(e);}};panel.Children.Add(button);window.Content=panel;window.ShowDialog();}
 private async Task Start(){try{if(session.Mode!="Record"||installer!=null)return;var path=Path.GetFullPath(session.InstallerFileName,@"C:\NovaForgeInput");if(await Validation.Hash(path)!=session.InstallerSha256)throw new InvalidDataException("Installer-Prüfsumme stimmt nicht.");var working=Path.Combine(Path.GetTempPath(),"NovaForge-Record-"+Guid.NewGuid().ToString("N"));await FolderMedia.Copy(Path.GetDirectoryName(path)!,working,new Progress<BuildProgress>(),CancellationToken.None);path=Path.Combine(working,Path.GetFileName(path));UiAutomationEngine.InstallerDirectory=working;
  recorder=await MouseRecorder.Create(pid=>installer!=null&&UiAutomationEngine.ProcessFilter(installer.Id,path.EndsWith(".msi",StringComparison.OrdinalIgnoreCase),extra)(pid),step=>Dispatcher.BeginInvoke(()=>{steps.Add(step);list.ScrollIntoView(step);status.Text=steps.Count+" Schritte aufgenommen. Entwurf jederzeit speichern.";}),extra,message=>Dispatcher.BeginInvoke(()=>Error(new InvalidOperationException(message))),other.IsChecked==true);
  installer=UiAutomationEngine.StartInstaller(path,session.InstallerArguments);status.Text="Aufnahme läuft. Installer normal bedienen; zusätzliche Dialoge werden ebenfalls erfasst.";
 }catch(Exception e){recorder?.Dispose();Error(e);}}
 private void ConnectWindow(){var pick=new Window{Title="Zusatzfenster verbinden",Owner=this,Width=600,Height=440};var panel=new DockPanel();var box=new ListBox();var candidates=new List<(int Pid,string Title)>();foreach(AutomationElement e in AutomationElement.RootElement.FindAll(TreeScope.Children,Condition.TrueCondition)){try{if(e.Current.ProcessId!=Environment.ProcessId&&e.Current.Name.Length>0)candidates.Add((e.Current.ProcessId,e.Current.Name));}catch{}}box.ItemsSource=candidates.Select(x=>x.Title).ToList();void Connect(){if(box.SelectedIndex>=0){extra.Add(candidates[box.SelectedIndex].Pid);status.Text="Zusatzfenster verbunden; dort normal weiterarbeiten.";pick.Close();}}var button=new Button{Content="Ausgewähltes Fenster verbinden"};button.Click+=(_,_)=>Connect();DockPanel.SetDock(button,Dock.Bottom);panel.Children.Add(button);panel.Children.Add(box);box.MouseDoubleClick+=(_,_)=>Connect();pick.Content=panel;pick.ShowDialog();}
 private async Task Save(bool close){if(saving)return;saving=true;try{profile.DisplayName=name.Text;profile.Steps=steps.ToList();profile.VerificationFile=verification;profile.Tested=false;profile.TestedPlanSha256="";var hash=await SessionExports.Save(profile,Output);status.Text="Gespeichert: "+profile.DisplayName+" · "+steps.Count+" Schritte. "+(verification.Length==0?"Entwurf: Prüfdatei für frischen Test fehlt noch.":"Noch frisch testen.");if(close){for(var i=0;i<30;i++){if(await SessionExports.Accepted(Output,hash)){recorder?.Dispose();ShutdownGuest();return;}await Task.Delay(1000);}status.Text="Profil gespeichert. Hostübernahme noch nicht bestätigt. NovaForge auf dem Host öffnen; Sandbox bleibt zum Schutz der Aufnahme offen.";}}catch(Exception e){Error(e);}finally{saving=false;}}
 private static void ShutdownGuest()=>Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"shutdown.exe")){Arguments="/s /t 0",UseShellExecute=false,CreateNoWindow=true});
 private async Task Test(){testing=true;try{var plan=await RecordedProfile.Load(@"C:\NovaForgeInput\profile.json");plan.Validate();name.Text=plan.DisplayName;foreach(var step in plan.Steps)steps.Add(step);using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(30));await UiAutomationEngine.Replay(plan,Path.GetFullPath(session.InstallerFileName,@"C:\NovaForgeInput"),s=>Dispatcher.Invoke(()=>status.Text=s),timeout.Token);plan.Tested=true;plan.TestedPlanSha256=plan.PlanHash();plan.TestedAt=DateTimeOffset.UtcNow;var hash=await SessionExports.Save(plan,Output);status.Text="Wiederholung erfolgreich. Aufnahme gespeichert; warte auf Hostbestätigung.";for(var i=0;i<30;i++){if(await SessionExports.Accepted(Output,hash)){ShutdownGuest();return;}await Task.Delay(1000);}status.Text="Erfolgreiches Profil gespeichert. Host öffnen; Sandbox anschließend schließen.";}catch(Exception e){await File.WriteAllTextAsync(Path.Combine(Output,"test-error.txt"),e.ToString());Error(e);}finally{testing=false;}}
 [DllImport("user32.dll")]private static extern bool RegisterHotKey(IntPtr h,int id,uint modifiers,uint key);
 [DllImport("user32.dll")]private static extern bool UnregisterHotKey(IntPtr h,int id);
}
